// swift-tools-version: 6.1
// The swift-tools-version declares the minimum version of Swift required to build this package.

import PackageDescription

let package = Package(
    name: "PhoneValidator",
    platforms: [
        .iOS(.v13),
        .macOS(.v10_15),
        .tvOS(.v13),
        .watchOS(.v6)
    ],
    products: [
        .library(
            name: "PhoneValidator",
            targets: ["PhoneValidator"]),
    ],
    targets: [
        .target(
            name: "PhoneValidator",
            resources: [
                // Generated by Scripts/generate-metadata.py from a pinned
                // libphonenumber release; committed so a bare clone builds.
                .copy("Resources/PhoneNumberMetadata.json")
            ]),
        .testTarget(
            name: "PhoneValidatorTests",
            dependencies: ["PhoneValidator"]),
    ]
)

// Swift 7's import rule, today: a file must import every module whose members
// it uses, rather than leaning on another file's imports.
for target in package.targets where target.type != .system && target.type != .binary && target.type != .plugin {
    target.swiftSettings = (target.swiftSettings ?? []) + [.enableUpcomingFeature("MemberImportVisibility")]
}
